'use strict';
// SKELIVIA connected frontend. All business state comes from the authenticated server.
(() => {
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v:[],id=v=>String(v??''),same=(a,b)=>id(a)===id(b);
const navs={user:[['home','Vue d’ensemble'],['measures','Mes mesures'],['device','Ma souris'],['shares','Mes partages'],['help','Assistance'],['settings','Paramètres']],clinician:[['home','Patients suivis'],['recommendations','Prévention collective'],['reminders','Mes rappels'],['help','Assistance'],['settings','Paramètres']],employer:[['home','Recommandations'],['history','Historique'],['settings','Paramètres']],support:[['home','Mes tickets'],['maintenance','Maintenance'],['settings','Paramètres']],security:[['home','Vue d’ensemble'],['incidents','Alertes & incidents'],['patches','Mises à jour'],['accounts','Comptes & accès'],['certificates','Certificats'],['proofs','Sauvegardes & contrôles'],['components','Composants'],['audit','Journal de sécurité'],['deletions','Suppressions'],['settings','Paramètres']]};
const roles={user:'Utilisateur',clinician:'Soignant',employer:'Employeur / prévention',support:'Support',security:'Administration sécurité'};
const labels={synthetic_reference:'Référence synthétique',awaiting_approval:'Accord du propriétaire attendu',diagnostic_request:'Diagnostic temporaire',calibration:'Calibration',update:'Mise à jour',replace:'Remplacement',certificate:'Certificat',delete:'Suppression',account_provision:'Provisionnement du compte',inventory:'Inventorié',backup:'Sauvegarde',qualification:'Qualification',action:'Action',verification:'Vérification',todo:'À traiter',in_progress:'En cours',done:'Réalisée',blocked:'Bloquée',waiting:'En attente',resolved:'Résolu',pending:'En attente',requested:'Demandé',approved:'Approuvé',deferred:'Différé',review:'À évaluer',confirmed:'Incident confirmé',false_positive:'Fausse alerte',closed:'Clos',active:'Actif',revoked:'Révoqué',expired:'Expiré',unknown:'État inconnu',stale:'Données anciennes',connected:'Connectée',disconnected:'Déconnectée',valid:'Valide',invalid:'Non exploitable',verified:'Vérifiée',success:'Vérifié',failed:'Échec',completed:'Terminé',low:'Faible',medium:'Modérée',high:'Haute',critical:'Critique',contact:'Temps de contact',pressure:'Appuis relatifs',moves:'Mouvements',equipment:'Équipement',layout:'Aménagement',organisation:'Organisation',advice:'Conseil',report:'Bilan',renew:'Renouvellement',revoke:'Révocation'};
const label=v=>labels[v]||v||'Non renseigné';
const st={session:null,data:null,csrf:'',page:'home',patient:null,ticket:null,tab:'measures',period:'week',busy:false,epoch:0,requests:new Set(),timer:null,dialogContext:null};
const paths = {home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',chart:'M4 3v17h17M8 15l4-5 4 3 5-8',advice:'M4 4h16v13H8l-4 4V4M8 8h8M8 12h6',share:'M8 12l8-5M8 12l8 5M5 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6M19 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6M19 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6',mouse:'M12 2a7 7 0 0 0-7 7v6a7 7 0 0 0 14 0V9a7 7 0 0 0-7-7ZM12 2v7M5 10h14',help:'M4 13v-2a8 8 0 0 1 16 0v2M4 12H2v6h4v-6H4M20 12h2v6h-4v-6h2M18 18v3h-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',people:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3M17 5a3 3 0 0 1 0 6M19 14a4 4 0 0 1 3 4v3',calendar:'M4 5h16v16H4V5M7 2v6M17 2v6M4 10h16M8 14h2M14 14h2M8 18h2',history:'M4 7a9 9 0 1 1-1 8M3 3v5h5M12 7v5l3 2',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4ZM9 12l2 2 4-4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',arrow:'M5 12h14M14 7l5 5-5 5',download:'M12 3v12M7 10l5 5 5-5M4 15v6h16v-6',check:'M5 12l4 4L19 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',alert:'M12 3 2 21h20L12 3ZM12 9v5M12 17v1',file:'M6 2h8l5 5v15H6V2M14 2v6h5M9 12h7M9 16h7',key:'M8 15a6 6 0 1 0 0-12 6 6 0 0 0 0 12M12 13l9 9M16 17l3-3M19 20l3-3',server:'M3 3h18v7H3V3M3 14h18v7H3v-7M7 6h1M7 17h1',refresh:'M3 10a9 9 0 0 1 16-6l2 3M21 2v5h-5M21 14a9 9 0 0 1-16 6l-2-3M3 22v-5h5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l4 2',logout:'M9 3H3v18h6M9 12h12M16 7l5 5-5 5'};
const icon = originalName => {const name=({measures:"chart",device:"mouse",shares:"share",recommendations:"advice",reminders:"calendar",maintenance:"history",incidents:"alert",patches:"refresh",accounts:"people",certificates:"key",proofs:"server",components:"server",audit:"file",deletions:"logout"})[originalName]||originalName;return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;};
const button=(text,action,ident='',variant='secondary',extra='')=>`<button type="button" class="button ${variant}" data-action="${esc(action)}" data-id="${esc(ident)}" ${extra}>${text}</button>`;
const badge=(value,type)=>`<span class="status ${type||(['valid','verified','success','done','approved','active'].includes(value)?'ok':['blocked','failed','expired','revoked','stale'].includes(value)?'warn':'info')}"><i aria-hidden="true"></i>${esc(label(value))}</span>`;
const empty=(title='Aucune information disponible',body='Les informations apparaîtront lorsqu’elles seront disponibles dans votre périmètre.')=>`<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;
const section=(title,description,body,actions='',cls='')=>`<section class="section ${cls}"><div class="section-heading"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div>${actions}</div>${body}</section>`;
const header=(kicker,title,subtitle='',actions='')=>`<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1><span class="title-lettering">${esc(title)}</span></h1><p class="page-subtitle">${esc(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`;
const field=(text,name,value='',type='text',extra='required')=>`<div class="field"><label for="f-${esc(name)}">${esc(text)}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const textarea=(text,name,value='')=>`<div class="field"><label for="f-${esc(name)}">${esc(text)}</label><textarea id="f-${esc(name)}" name="${esc(name)}" maxlength="2000" required>${esc(value)}</textarea></div>`;
const select=(text,name,options,value='')=>`<div class="field"><label for="f-${esc(name)}">${esc(text)}</label><select id="f-${esc(name)}" name="${esc(name)}" ${name==='device_id'?'':'required'}>${options.map(([v,t])=>`<option value="${esc(v)}" ${same(v,value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
const check=(text,name,checked=false,required=false)=>`<label class="field-check"><input type="checkbox" name="${esc(name)}" ${checked?'checked':''} ${required?'required':''}>${esc(text)}</label>`;
const table=(heads,rows)=>rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();
const date=v=>{if(!v)return 'Non renseigné';const d=new Date(typeof v==='number'?v*1000:v);return Number.isNaN(d.getTime())?'Date indisponible':d.toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'});};
const day=v=>{if(!v)return '—';const d=new Date(typeof v==='number'?v*1000:v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('fr-FR');};
const collection=name=>arr(st.data?.[name]);
const role=()=>st.session?.user?.role;
const currentPatient=()=>collection('patients').find(p=>same(p.id,st.patient));
const access=()=>role()!=='clinician'||Boolean(currentPatient()?.access);
const measureValue=(m,key)=>m.quality==='invalid'?null:m.metrics?.[key];
const personMeasures=()=>arr(st.measurePage?.rows||st.data?.measures).filter(m=>role()!=='clinician'||same(m.patient_id,st.patient));
const partialMeasures=()=>Boolean(st.measurePage?st.measurePage.has_more:st.data?.measures_has_more);
function pressureSummary(rows){const points=rows.filter(m=>typeof measureValue(m,'thumb_pct')==='number'),timed=points.filter(m=>Number(m.window_duration_seconds??m.metrics?.window_duration_seconds)>0);if(!points.length)return {value:'—',caption:'Aucune valeur exploitable'};if(timed.length&&timed.length!==points.length)return {value:'—',caption:'Fenêtres hétérogènes : moyenne indisponible'};if(timed.length){const duration=m=>Number(m.window_duration_seconds??m.metrics?.window_duration_seconds);return {value:Math.round(points.reduce((sum,m)=>sum+measureValue(m,'thumb_pct')*duration(m),0)/points.reduce((sum,m)=>sum+duration(m),0)),caption:'Moyenne pondérée par durée · pouce'};}return {value:Math.round(points.reduce((sum,m)=>sum+measureValue(m,'thumb_pct'),0)/points.length),caption:'Moyenne des points · durée absente'};}
let measuresSequence=0;
async function loadMeasures(append=false){if(!st.data||!['user','clinician'].includes(role()))return;if(role()==='clinician'&&!currentPatient()?.access){st.measurePage=null;return;}const seq=++measuresSequence,patient=role()==='clinician'?st.patient:'',end=st.measureEnd||st.data.measure_window?.end||String(st.data.server_time).slice(0,10),startDate=new Date(end+'T00:00:00Z');startDate.setUTCDate(startDate.getUTCDate()-({day:0,week:6,month:29}[st.period]));const start=startDate.toISOString().slice(0,10),query=new URLSearchParams({start,end,limit:'1000'});if(patient)query.set('patient_id',patient);const previous=st.measurePage;if(append){if(!previous?.next_cursor)return;query.set('cursor',previous.next_cursor);}const result=await api('/api/measures?'+query);if(seq!==measuresSequence||!st.data||patient!==(role()==='clinician'?st.patient:''))return;const rows=append?[...previous.rows,...arr(result.measures)]:arr(result.measures);st.measurePage={rows:[...new Map(rows.map(m=>[m.id,m])).values()],window:result.window,has_more:result.has_more,next_cursor:result.next_cursor,patient};}

const author=d=>d.author_name||(same(d.author_id,st.session?.user?.id)?st.session.user.name:collection('clinicians').find(c=>same(c.id,d.author_id))?.name)||d.author_id||'Professionnel habilité';
const docs=()=>collection('documents').filter(d=>role()!=='clinician'||same(d.patient_id,st.patient));
const latestDocs=kind=>Object.values(docs().filter(d=>d.kind===kind).reduce((out,d)=>{const key=d.document_id||d.id;if(!out[key]||Number(d.version)>Number(out[key].version))out[key]=d;return out;},{}));
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(st.toast);st.toast=setTimeout(()=>$('#toast').hidden=true,7000);}
function clearWorkspace(){window.SkeliviaPush?.reset();st.epoch++;for(const c of st.requests)c.abort();st.requests.clear();st.data=null;st.measurePage=null;st.measureEnd=null;measuresSequence++;st.patient=null;st.ticket=null;closeDialog();$('#content').replaceChildren();$('#navigation').replaceChildren();$('#account-label').textContent='';$('#account-role').textContent='';$('#account-avatar').textContent='';$('#workspace').hidden=true;$('#password').value='';$('#otp').value='';}
async function api(path,options={}){const controller=new AbortController(),epoch=st.epoch;st.requests.add(controller);try{const r=await fetch(path,{credentials:'same-origin',cache:'no-store',signal:controller.signal,method:options.method||'GET',headers:{Accept:'application/json',...(options.method?{'Content-Type':'application/json','X-CSRF-Token':st.csrf}:{})},...(options.body?{body:JSON.stringify(options.body)}:{})});const body=await r.json().catch(()=>({}));if(epoch!==st.epoch)throw new DOMException('Réponse périmée','AbortError');if(!r.ok){const error=new Error(typeof body.detail==='string'?body.detail:r.status===422?'Vérifiez les champs saisis.':'L’opération n’est pas autorisée ou disponible.');error.status=r.status;throw error;}return body;}finally{st.requests.delete(controller);}}
async function failure(e){if(e.name==='AbortError')return;if(e.status===401){clearWorkspace();st.session=null;await loadSession();toast('Votre session n’est plus active. Reconnectez-vous.');return;}if(e.status===403&&/authent|réauth|recent|récente/i.test(e.message)){reauthenticate();return;}if(e.status===403||e.status===404){closeDialog();st.data=null;$('#content').innerHTML=empty('Accès indisponible','Votre autorisation a changé. Les données précédentes ont été retirées.');await reload().catch(()=>{});}toast(e instanceof TypeError?'Le service ne répond pas. Réessayez lorsque la connexion est rétablie.':e.message);}
async function loadSession(){try{const session=await api('/api/session');st.session=session;st.csrf=session.csrf_token||'';$('#retry-session').hidden=true;if(session.authenticated&&session.user&&navs[session.user.role]){$('#login-screen').hidden=true;$('#workspace').hidden=false;await reload();if(st.openNotifications||new URLSearchParams(location.search).get('notifications')==='1'){st.openNotifications=false;const url=new URL(location.href);url.searchParams.delete('notifications');window.history.replaceState(null,'',url.pathname+url.search+url.hash);$('#notifications').click();}}else{clearWorkspace();st.session=session;st.csrf=session.csrf_token||'';const oidc=session.auth_mode==='oidc'||session.authentication_mode==='oidc'||session.environment==='target'||session.environment?.auth_mode==='oidc'||session.environment?.auth==='oidc'||session.oidc_enabled===true;$('#login-screen').hidden=false;$('#login-form').hidden=oidc;$('#oidc-login').hidden=!oidc;$('#oidc-login').href=['/oidc/login','/auth/login'].includes(session.login_url)?session.login_url:'/auth/login';$('#local-help').hidden=oidc;$('#login-mode').textContent=oidc?'Utilisez votre identité professionnelle pour accéder à votre espace.':'Connexion au banc local avec authentification à deux facteurs.';}}catch(e){clearWorkspace();$('#login-screen').hidden=false;$('#retry-session').hidden=false;$('#login-mode').textContent='Le service est indisponible. Aucune donnée de compte n’est affichée.';}}
let reloadSequence=0;
async function reload(keepMeasures=false){if(!st.session?.authenticated)return;const seq=++reloadSequence;$('#content').setAttribute('aria-busy','true');try{const data=await api('/api/workspace');if(seq!==reloadSequence)return;if(data.role!==role())throw Object.assign(new Error('Le rôle du compte a changé. Reconnectez-vous.'),{status:401});const previousScope=JSON.stringify([st.data?.patients,st.data?.measures,st.data?.documents]);const preserve=keepMeasures&&st.measurePage&&JSON.stringify([st.data?.role,st.data?.patient_id,st.data?.patients,st.data?.measure_window])===JSON.stringify([data.role,data.patient_id,data.patients,data.measure_window]);st.data=data;if(!preserve){st.measurePage=null;await loadMeasures();}if(seq!==reloadSequence)return;if(st.dialogContext?.patient&&previousScope!==JSON.stringify([data.patients,data.measures,data.documents]))closeDialog();if(st.dialogContext?.patient&&!collection('patients').some(p=>same(p.id,st.dialogContext.patient)&&p.access))closeDialog();render();$('#content').setAttribute('aria-busy','false');}catch(e){st.data=null;$('#content').innerHTML=empty('Espace non disponible','Les données précédentes ont été retirées. Utilisez Actualiser pour réessayer.');$('#content').setAttribute('aria-busy','false');throw e;}}
async function mutate(action,payload){const result=await api('/api/actions',{method:'POST',body:{action,payload}});closeDialog();await reload();toast(result.message||'Demande enregistrée par le service.');return result;}
let dialogCallback=null,dialogOpener=null;
function dialog(title,html,submit='',callback=null,context=null){if(!$('#dialog').open)dialogOpener=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog-error').hidden=true;$('#dialog-submit').hidden=!submit;$('#dialog-submit').textContent=submit;$('#dialog-cancel').textContent=submit?'Annuler':'Fermer';dialogCallback=callback;st.dialogContext=context;if(!$('#dialog').open)$('#dialog').showModal();($('input,select,textarea,button',$('#dialog-content'))||$('#dialog-close')).focus();}
function closeDialog(){if($('#dialog').open)$('#dialog').close();$('#dialog-content').replaceChildren();dialogCallback=null;st.dialogContext=null;}
function actionForm(title,html,action,payload={},transform=form=>Object.fromEntries(form),submit='Enregistrer'){dialog(title,html,submit,async form=>mutate(action,{...payload,...transform(form)}),role()==='clinician'&&st.page==='patient'?{patient:st.patient}:null);}
function menu(open){$('#sidebar').classList.toggle('open',open);$('#backdrop').hidden=!open;$('#open-menu').setAttribute('aria-expanded',String(open));$('.workspace').inert=open&&matchMedia('(max-width:800px)').matches;if(matchMedia('(max-width:800px)').matches){if(open)$('#close-menu').focus();else $('#open-menu').focus();}}
function go(page){st.page=page;menu(false);render();$('#content').focus();window.scrollTo(0,0);}
function setupTables(){for(const [i,wrap]of $$('.table-wrap').entries()){const overflow=wrap.scrollWidth>wrap.clientWidth+1;wrap.tabIndex=overflow?0:-1;if(overflow){wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Tableau défilant horizontalement');const hint=document.createElement('p');hint.className='table-scroll-hint';hint.textContent='Faites défiler le tableau →';hint.id='table-hint-'+i;wrap.before(hint);wrap.setAttribute('aria-describedby',hint.id);}}}
function filteredMeasures(){if(st.measurePage)return personMeasures().slice().sort((a,b)=>new Date(a.recorded_at)-new Date(b.recorded_at));const rows=personMeasures();if(!rows.length)return [];const validTimes=rows.map(m=>new Date(m.recorded_at).getTime()).filter(Number.isFinite);if(!validTimes.length)return rows;const latest=Math.max(...validTimes),duration={day:864e5,week:7*864e5,month:31*864e5}[st.period];return rows.filter(m=>new Date(m.recorded_at).getTime()>latest-duration).sort((a,b)=>new Date(a.recorded_at)-new Date(b.recorded_at));}
const metrics=[['contact_seconds','Temps de contact détecté','secondes','#164bd6'],['thumb_pct','Appuis relatifs','% relatif','#007d87'],['episodes','Épisodes de mouvement','épisodes','#007d87']];
function chart(rows,key,unit,color){const values=rows.map(m=>measureValue(m,key)),paired=key==='thumb_pct',alternate=paired?rows.map(m=>measureValue(m,'palm_pct')):[],numbers=[...values,...alternate].filter(v=>typeof v==='number'&&Number.isFinite(v));if(!numbers.length)return empty('Mesure non disponible','Cette catégorie n’est pas partagée ou aucune mesure exploitable n’a été reçue.');const max=Math.max(...numbers,1),width=320,height=150,pad=28,step=(width-pad*2)/Math.max(rows.length,1),bar=Math.min(paired?20:28,step*(paired?.3:.65));const rect=(v,x,fill,title)=>typeof v==='number'&&Number.isFinite(v)?`<rect x="${x}" y="${height-125*v/max}" width="${bar}" height="${125*v/max}" rx="1" fill="${fill}"><title>${esc(title)} : ${v} ${unit}</title></rect>`:`<text x="${x+bar/2}" y="${height-10}" text-anchor="middle">—</text>`;return `<svg class="live-chart" viewBox="0 0 ${width} ${height+22}" role="img" aria-label="${esc(unit)}. ${paired?'Pouce en turquoise, paume en bleu. ':''}Les valeurs manquantes ne sont pas remplacées par zéro."><path d="M${pad} 12V${height}H310" stroke="#dce4eb" fill="none"/><text x="0" y="20">${Math.round(max)}</text><text x="12" y="${height}">0</text>${values.map((v,i)=>{const x=pad+i*step+step/2;return rect(v,x-(paired?bar+2:bar/2),color,day(rows[i].recorded_at)+(paired?' · Pouce':''))+(paired?rect(alternate[i],x+2,'#164bd6',day(rows[i].recorded_at)+' · Paume'):'');}).join('')}<text x="${pad}" y="169">${esc(day(rows[0].recorded_at))}</text><text x="310" y="169" text-anchor="end">${esc(day(rows.at(-1).recorded_at))}</text></svg>${paired?'<div class="chart-legend"><span><i class="legend-line"></i>Pouce</span><span><i class="legend-line blue"></i>Paume</span></div>':''}`;}
function measures(){const rows=filteredMeasures();return section(role()==='clinician'?'Mesures partagées':'Vos mesures en perspective',st.measurePage?`${day(st.measurePage.window.start)} – ${day(st.measurePage.window.end)} · ${rows.length} mesure(s) chargée(s)`:'Les lacunes restent visibles.',`<div class="table-toolbar"><label for="measure-end">Fin de la période</label><input id="measure-end" type="date" value="${esc(st.measureEnd||st.measurePage?.window.end||st.data?.measure_window?.end||'')}" aria-label="Fin de la période de mesures"></div>`+(rows.length?`<div class="chart-grid">${metrics.map(([key,title,unit,color])=>{const values=rows.map(r=>measureValue(r,key)).filter(v=>typeof v==='number'&&Number.isFinite(v)),value=partialMeasures()?'—':key==='thumb_pct'?pressureSummary(rows).value:values.length?values.reduce((a,b)=>a+b,0):'—';return `<div class="chart-cell"><p class="chart-label">${title}</p><p class="chart-value">${value}<small>${unit}</small></p><p class="chart-caption">${partialMeasures()?'Synthèse suspendue : période incomplète':key==='thumb_pct'?pressureSummary(rows).caption:'Cumul des mesures disponibles'}</p>${chart(rows,key,unit,color)}</div>`;}).join('')}</div><div class="section-footer">${partialMeasures()?`<p class="notice warn">La période est incomplète. Chargez la suite avant de lire les cumuls ou de comparer.</p>${button('Charger la suite','measures.more','','secondary')}`:''}Points non exploitables exclus de la synthèse. Qualité et calibration dans le détail. Les mesures seules ne démontrent pas une évolution de santé.</div>`:empty('Aucune mesure disponible','Les mesures reçues et autorisées apparaîtront ici.')),`<div class="period-switch" aria-label="Période">${[['day','Jour'],['week','Semaine'],['month','Mois']].map(([v,l])=>`<button data-period="${v}" aria-pressed="${st.period===v}">${l}</button>`).join('')}</div>`);}
function deviceStrip(){const d=collection('devices')[0];return d?`<div class="status-strip"><div><p class="device-name">Votre souris SKELIVIA</p><p class="device-description">${esc(d.id)}</p></div><div class="strip-item"><small>Connexion</small>${badge(d.connection||'unknown')}</div><div class="strip-item last-seen"><small>Dernières données</small><strong>${date(d.last_seen)}</strong></div><div class="strip-item"><small>Calibration</small>${badge(d.calibration_status||'unknown')}<small>${esc(d.calibration||'Référence non disponible')}</small></div>${button('Vérifier la souris','page:device','','secondary small')}</div>`:section('Votre souris','Association de l’appareil',empty('Aucune souris associée','Contactez le support pour préparer l’association de votre appareil.'));}
function documentCards(kind){const entries=latestDocs(kind);return entries.length?entries.map(d=>`<article class="advice"><div class="advice-header"><h3>${esc(d.title||label(kind))}</h3><span class="tag">${esc(label(kind))}</span></div><p>${esc(d.body)}</p><div class="document-meta"><span>${date(d.created_at)} · ${esc(author(d))}</span><span>Version ${esc(d.version)}</span></div>${role()==='clinician'?`<div class="version-actions">${button('Nouvelle version','document.edit',d.id,'quiet small')}${button('Historique','document.history',d.document_id||d.id,'quiet small')}</div>`:''}</article>`).join(''):empty(kind==='advice'?'Aucun conseil publié':'Aucun bilan disponible','Les publications du soignant apparaîtront ici.');}
function jobs(){return collection('jobs').length?section('Demandes en cours','Un enregistrement ne confirme pas une exécution matérielle.',table(['Demande','Cible','État','Résultat'],collection('jobs').map(j=>[esc(label(j.kind)),esc(j.target_id),badge(j.status),esc(typeof j.result==='string'?j.result:j.result?.detail||j.result?.message||'En attente de résultat vérifié')]))):'';}
function userHome(){return header('Votre espace personnel','Votre journée, en un regard','Vos informations de suivi et la disponibilité de votre souris.')+deviceStrip()+measures()+`<div class="two-columns">${section('Conseils de prévention','Sélectionnés par votre soignant',documentCards('advice'))}${section('Bilan de fin de suivi','Conclusions et conseils à conserver',documentCards('report'))}</div>`;}
function measuresPage(){return header('Évolution des mesures','Mes mesures','Mesures reçues, qualité et périodes manquantes.',button('Télécharger un bilan','export.personal','','secondary'))+measures()+section('Détail de la période','Les unités sont celles transmises par le service.',table(['Date','Contact · s','Pouce · %','Paume · %','Mouvements','Qualité','Calibration'],filteredMeasures().map(m=>[date(m.recorded_at),esc(m.metrics?.contact_seconds??'—'),esc(m.metrics?.thumb_pct??'—'),esc(m.metrics?.palm_pct??'—'),esc(m.metrics?.episodes??'—'),badge(m.quality),esc(m.calibration||'Non renseignée')])));}
function devicePage(){return header('Appareil & maintenance','Ma souris','Les résultats proviennent du service et de l’appareil.')+deviceStrip()+collection('devices').map(d=>section('Calibration et logiciel',d.id,`<div class="section-body"><dl class="details-grid"><div><dt>Version installée</dt><dd>${esc(d.firmware||'Non renseignée')}</dd></div><div><dt>Calibration</dt><dd>${esc(d.calibration||'Non renseignée')}</dd></div></dl><p class="help-text">Une demande de calibration reste en attente tant que l’appareil n’a pas confirmé le résultat.</p><div class="action-grid">${button('Calibration guidée','device.calibrate',d.id,'primary')}${button('Perte ou remplacement','device.loss',d.id,'secondary')}</div></div>`)).join('')+jobs();}
function sharesPage(){return header('Vous gardez la main','Mes partages','Choisissez le destinataire, la période, les catégories et la durée.',button('+ Nouveau partage','share.create','','primary'))+section('Partages accordés','La révocation retire les accès futurs.',table(['Soignant','Période et catégories','Expiration','État','Action'],collection('shares').map(s=>[esc(collection('clinicians').find(c=>same(c.id,s.clinician_id))?.name||s.clinician_id),`${day(s.start)} – ${day(s.end)}<small>${arr(s.categories).map(c=>esc(label(c))).join(' · ')}</small>`,date(s.expires),badge(!s.active?'revoked':Number(s.expires)*1000<Date.now()?'expired':'active'),s.active?button('Révoquer','share.revoke',s.id,'secondary small'):'—'])));}
function reminders(){return collection('reminders').length?`<ul class="record-list">${collection('reminders').map(r=>`<li><strong>${day(r.due)}</strong><p>${esc(r.body)}</p><small>${esc(collection('patients').find(p=>same(p.id,r.patient_id))?.name||r.patient_id)}</small><div>${button('Ouvrir le dossier','patient',r.patient_id,'quiet small')}${button('Supprimer le rappel','reminder.delete',r.id,'quiet small')}</div></li>`).join('')}</ul>`:empty('Aucun rappel programmé');}
function clinicianHome(){return header('Vos suivis autorisés','Patients suivis','L’accès exige une relation de suivi et un partage actif.',button('+ Ajouter un rappel','reminder.create','','secondary'))+`<div class="work-split">${section('Vos patients','Les dossiers fermés ne dévoilent aucune mesure.',`<div class="table-toolbar"><div class="search-field"><input id="patient-search" aria-label="Rechercher un patient" placeholder="Rechercher un patient…"></div></div>`+table(['Patient','Partage','Dossier'],collection('patients').map(p=>[`${esc(p.name)}<small>${esc(p.id)}</small>`,badge(p.access?'active':'Accès fermé'),p.access?button('Consulter →','patient',p.id,'quiet small'):'Accès fermé'])))}${section('À réexaminer','Vos rappels personnels',reminders())}</div>`+measurementUpdates();}
function measurementUpdates(){const updates=collection('measurement_updates');return updates.length?section('Informations sur les mesures','Évolution des versions et comparabilité.',`<ul class="record-list">${updates.map(u=>`<li><strong>${esc(u.title)} · ${esc(u.version)}</strong><p>${esc(u.comparability)}</p></li>`).join('')}</ul>`):'';}
function patientPage(){const p=currentPatient();if(!p?.access)return header('Accès fermé','Dossier non accessible','Le partage a expiré ou a été révoqué.',button('Retour aux patients','page:home'));let body=st.tab==='measures'?`<div class="section-body">${button('Comparer deux périodes','compare','','secondary')}</div>${measures()}${section('Qualité et calibration','Références des mesures autorisées.',table(['Date de mesure','Qualité','Calibration','Date de calibration'],filteredMeasures().map(m=>[date(m.recorded_at),badge(m.quality),esc(m.calibration||'Non renseignée'),date(m.calibration_at)])))}`:documentCards(st.tab==='advice'?'advice':'report')+`<div class="section-body">${button(st.tab==='advice'?'Rédiger un conseil':'Rédiger le bilan','document.new',st.tab==='advice'?'advice':'report','primary')}</div>`;return button('← Tous les patients','page:home','','quiet')+header(p.id,p.name,'Données limitées au partage actif.')+section('Dossier autorisé','',`<div class="tabs" role="tablist" aria-label="Dossier patient">${[['measures','Mesures'],['advice','Conseils'],['report','Bilan de suivi']].map(([v,l])=>`<button id="tab-${v}" role="tab" data-tab="${v}" aria-controls="patient-panel" aria-selected="${st.tab===v}" tabindex="${st.tab===v?0:-1}">${l}</button>`).join('')}</div><div id="patient-panel" role="tabpanel" aria-labelledby="tab-${st.tab}">${body}</div>`);}
function recommendations(){const editable=role()==='employer';return table(['Référence / publication','Recommandation','Type','Avancement'],collection('recommendations').map(r=>[`${esc(r.id)}<small>${date(r.created_at)}</small>`,`<strong>${esc(r.title)}</strong><p class="document-text">${esc(r.body)}</p>${role()==='clinician'?button('Modifier la recommandation','recommendation.revise',r.id,'quiet small'):''}`,esc(label(r.category)),editable?`<select data-rec-status="${esc(r.id)}" aria-label="Avancement de ${esc(r.title)}">${['todo','in_progress','done','blocked'].map(v=>`<option value="${v}" ${r.status===v?'selected':''}>${label(v)}</option>`).join('')}</select>`:badge(r.status)]));}
function employerHome(){return header('Agir sur les conditions de travail','Votre prévention, en actions','Des recommandations organisationnelles, sans données médicales individuelles.',button('Télécharger le récapitulatif','export.prevention','','secondary'))+`<div class="count-strip">${['todo','in_progress','done','blocked'].map(s=>`<div class="count-item" data-count-status="${label(s)}"><strong>${collection('recommendations').filter(r=>r.status===s).length}</strong><span>${label(s)}</span></div>`).join('')}</div>`+section('Recommandations publiées','Mettez à jour leur avancement.',recommendations());}
function history(){return header('Actions de prévention','Historique','Dates des changements de statut.')+section('Derniers changements','',table(['Recommandation','Date','Statut'],collection('recommendations').flatMap(r=>arr(r.history).map(h=>[esc(r.title),date(h.at||h.created_at),badge(h.status)]))));}
function ticket(){return collection('tickets').find(t=>same(t.id,st.ticket))||collection('tickets')[0];}
function thread(t){return arr(t.messages).map(m=>`<div class="ticket-message"><small>${esc(m.author_name||m.author_id)} · ${date(m.at)}</small><p class="document-text">${esc(m.body)}</p></div>`).join('')||'<p class="muted">Aucun échange disponible.</p>';}
function ticketDetail(t){if(!t)return section('Détail du ticket','',empty('Sélectionnez un ticket'));const hardware=Boolean(t.device_id),active=t.diagnostic_active===true,d=collection('devices').find(d=>same(d.id,t.device_id));return section(t.title,`${t.id}${hardware?' · '+t.device_id:' · Assistance du service'}`,`<div class="section-body"><div class="ticket-navigation">${button('← Mes tickets','ticket.back','','quiet mobile-back')}</div><div class="ticket-current-status">${badge(t.status)}</div>${hardware?`<dl class="details-grid"><div><dt>Diagnostic temporaire</dt><dd>${badge(active?'active':'Accès fermé')}</dd></div><div><dt>Expiration</dt><dd>${date(t.diagnostic_expires)}</dd></div>${active?`<div><dt>Logiciel installé</dt><dd>${esc(d?.firmware||'Non renseigné')}</dd></div><div><dt>Connexion</dt><dd>${esc(label(d?.connection))}</dd></div>`:''}</dl><p class="help-text">${active?'Les actions concernent uniquement cet appareil et cette intervention.':'Le diagnostic est fermé. Ses informations ne sont plus consultables.'}</p><div class="action-grid">${active?button('Calibration','device.calibrate',t.device_id,'secondary small')+button('Mise à jour','device.update',t.id,'secondary small')+button('Remplacement','device.replace',t.id,'secondary small')+button('Fermer le diagnostic','diagnostic.revoke',t.id,'quiet small'):button('Demander un diagnostic','diagnostic.request',t.id,'secondary small')}${button('Historique technique','page:maintenance','','quiet small')}</div>`:'<p class="notice">Demande relative au service. Aucun appareil patient n’est associé à ce ticket.</p>'}<h3 class="subsection-title">Échanges techniques</h3>${thread(t)}${button('Répondre','ticket.reply',t.id,'primary small')}${hardware&&active?`<h3 class="subsection-title">Vérifications de fin d’intervention</h3><div class="checklist">${['connection','sensors','calibration'].map((key,i)=>`<label class="field-check"><input type="checkbox" data-check="${key}" ${t.checks?.[key]?'checked':''}>${['Connexion vérifiée','Capteurs vérifiés','Calibration vérifiée'][i]}</label>`).join('')}</div>${button('Enregistrer les contrôles','ticket.checks',t.id,'secondary small')}<p class="help-text">La clôture nécessite aussi un résultat matériel vérifié par le service.</p>`:''}<div class="action-grid">${button('Modifier le statut','ticket.status',t.id,'secondary small')}${button('Signaler une anomalie','security.report',t.id,'quiet small')}</div></div>`,'','ticket-detail');}
function supportHome(){const current=ticket();if(current)st.ticket=current.id;return header('Interventions attribuées','Votre file de support','Des informations techniques ciblées, sans données d’usage ni contenu médical.')+`<div class="support-layout ${st.ticketOpen?'has-selection':''}">${section('Mes tickets',`${collection('tickets').length} ticket(s) attribué(s)`,collection('tickets').length?`<div class="ticket-list">${collection('tickets').map(t=>`<button class="ticket-button" data-action="ticket.open" data-id="${esc(t.id)}" aria-pressed="${same(t.id,st.ticket)}"><span class="ticket-meta"><span>${esc(t.id)}</span><span>${day(t.created_at)}</span></span><h3>${esc(t.title)}</h3>${badge(t.status)}<p>${esc(t.device_id||'Assistance du service')}</p></button>`).join('')}</div>`:empty('Aucun ticket attribué'),'','ticket-list-section')}${ticketDetail(current)}</div>`+jobs();}
function maintenance(){const t=ticket(),d=collection('devices').find(d=>same(d.id,t?.device_id));return header('Ticket attribué','Maintenance technique','Historique technique de l’appareil sélectionné.',button('Retour au ticket','page:home'))+(d?section(d.id,'Interventions enregistrées',table(['Date','Intervention','Résultat'],arr(d.history).map(h=>[date(h.at||h.created_at),esc(h.title||h.kind||h.action),esc(h.body||h.result?.message||h.status||'Non renseigné')]))):section('Historique','',empty('Aucun historique matériel','Sélectionnez un ticket associé à un appareil.')))+jobs();}
function helpPage(){return header('Assistance technique','Vos demandes au support','N’incluez aucun dossier patient ni contenu médical.',button('+ Nouveau ticket','ticket.create','','primary'))+section('Mes tickets','Échanges avec le support',collection('tickets').length?`<ul class="record-list">${collection('tickets').map(t=>`<li><div class="row"><strong>${esc(t.title)}</strong>${badge(t.status)}</div><small>${esc(t.id)} · ${date(t.created_at)}</small><div>${button('Ouvrir les échanges','help.open',t.id,'quiet small')}</div></li>`).join('')}</ul>`:empty('Aucune demande'))+section('Diagnostics à autoriser','L’accès technique reste limité dans le temps.',collection('jobs').filter(j=>j.kind==='diagnostic_request'&&['pending','requested','awaiting_approval'].includes(j.status)).map(j=>`<div class="section-body"><p>${esc(j.target_id)} · ${date(j.created_at)}</p>${button('Examiner la demande','diagnostic.approve',j.id,'secondary')}</div>`).join('')||empty('Aucune demande en attente'));}
function incidents(){return collection('incidents').length?collection('incidents').map(i=>`<div class="security-alert"><div class="alert-icon">${icon('file')}</div><div><h3>${esc(i.title||'Événement de sécurité')}</h3><p>${esc(i.id)} · ${esc(i.body||i.description||'Éléments techniques à examiner')}</p>${badge(i.status)}</div>${button(['confirmed','closed'].includes(i.status)?'Ouvrir le dossier':'Examiner','incident.open',i.id,'secondary small')}</div>`).join(''):empty('Aucune alerte disponible','L’absence d’alerte ne prouve pas que tous les systèmes sont surveillés.');}
function patches(){return table(['Composant / version','Priorité','État','Action'],collection('patches').map(p=>[`${esc(p.title||p.component)}<small>${esc(p.version)}</small>`,esc(label(p.priority)),badge(p.status||p.decision),button('Évaluer','patch.evaluate',p.id,'secondary small')]));}
function protections(){const runtime=st.data.runtime_status||{},runtimeLabel=({connected:'Signal reçu',disconnected:'Déconnecté',stale:'Signal ancien',unknown:'Non renseigné'})[runtime.status]||'Non renseigné';return `<div class="health-row"><h3>Sauvegardes et restauration</h3><p>${collection('proofs').length} preuve(s) disponible(s)</p>${button('Voir les résultats','page:proofs','','quiet small')}</div><div class="health-row"><h3>Certificats</h3><p>${collection('certificates').length} certificat(s) suivis</p>${button('Consulter','page:certificates','','quiet small')}</div><div class="health-row"><h3>${esc(runtime.service||'Surveillance des connexions')}</h3>${badge(runtimeLabel,['stale','disconnected'].includes(runtime.status)?'warn':runtime.status==='connected'?'ok':'info')}<p>Dernier signal : ${date(runtime.last_seen)}</p><p class="footnote">${esc(runtime.scope||'Disponibilité de la surveillance non renseignée ; aucune couverture complète des journaux ne peut être déduite.')}</p>${button('Consulter le journal','page:audit','','quiet small')}</div>`;}
function adminHome(){return header('Protection des accès et des données','Surveillance et protections','Les états affichés proviennent des contrôles disponibles.')+section('Alertes à examiner','Événements techniques sans contenu médical',incidents())+`<div class="security-columns">${section('Mises à jour à traiter','Évaluation et décision',patches())}${section('État des protections','Résultats documentés',protections())}</div>`;}
function accountsPage(){return header('Comptes & autorisations','Comptes et accès','Les changements sensibles nécessitent une validation indépendante.',button('+ Demander une création','account.create','','primary'))+section('Comptes','Les rôles n’accordent aucun partage médical implicite.',table(['Compte','Rôle','État','Actions'],collection('accounts').map(a=>[`${esc(a.name)}<small>${esc(a.id)}</small>`,esc(roles[a.role]||a.role),badge(a.active?'active':'Suspendu'),`<div class="row-actions">${button('Sessions','account.sessions',a.id,'quiet small')}${!same(a.id,st.session.user.id)?button(a.active?'Suspendre':'Réactiver','account.toggle',a.id,'secondary small')+button('Rôle','account.role',a.id,'secondary small'):''}</div>`])))+section('Demandes de changement','Le demandeur ne peut pas approuver sa propre demande.',table(['Demande','Compte','État','Action'],collection('account_requests').map(r=>[esc(label(r.operation)),esc(r.target_id||r.name||r.username),badge(r.status),r.status==='pending'?(same(r.requester_id,st.session.user.id)||same(r.target_id,st.session.user.id)?'<span class="footnote">Validation par un autre administrateur</span>':button('Examiner','account.approve',r.id,'secondary small')):'—'])))+section('Accès temporaires','Contrôle des autorisations réellement présentes en base.',`<div class="section-body">${button('Vérifier les accès','access.check','','secondary')}</div>`);}
function certificates(){return header('Identité des appareils','Certificats','Le renouvellement ou la révocation doit être exécuté et vérifié.')+section('Certificats suivis','Aucune clé privée n’est affichée.',table(['Appareil','Échéance','État','Actions'],collection('certificates').map(c=>[esc(c.device_id||c.id),date(c.expires||c.expires_at),badge(c.revoked?'revoked':c.status||'active'),`<div class="row-actions">${button('Renouveler','certificate.renew',c.device_id||c.id,'secondary small')}${button('Révoquer','certificate.revoke',c.device_id||c.id,'danger small')}</div>`])))+jobs();}
function proofs(){return header('Vérifications documentées','Sauvegardes & contrôles','Un résultat absent ou en attente n’est pas une preuve de réussite.')+section('Résultats reçus','Sauvegardes, restauration et contrôles d’accès',table(['Contrôle','Date','Résultat','Détail'],collection('proofs').map(p=>[esc(p.kind||p.title),date(p.created_at),badge(p.status),esc(p.summary||p.result?.detail||p.result?.message||p.description||p.body||'Non renseigné')])))+jobs();}
function components(){return header('Versions et support','Composants','Inventaire déclaré par le service.')+section('Composants suivis','',table(['Composant','Version','Fin de support','État'],collection('components').map(c=>[esc(c.title||c.name||c.id),esc(c.version),day(c.support_end||c.end_of_support),badge(c.status)])));}
function audit(){return header('Traçabilité des actions','Journal de sécurité','Événements expurgés de tout contenu médical.')+section('Derniers événements','',table(['Date','Auteur','Action','Référence','Résultat'],collection('audit').map(a=>[date(a.at||a.created_at),esc(a.actor_name||a.actor_id||a.account_id),esc(a.action),esc(a.target_id||a.target),esc(label(a.result||a.status))])));}
function deletions(){return header('Droits des utilisateurs','Demandes de suppression','L’exécution reste distincte de la réception d’une demande.')+section('Demandes reçues','',table(['Référence','Date','État','Action'],collection('deletions').map(d=>[esc(d.id),date(d.created_at),badge(d.status),button('Examiner','deletion.review',d.id,'secondary small')])))+jobs();}
function settings(){const s=st.data?.settings||{};return header('Votre confort et vos accès','Paramètres','Préférences enregistrées pour votre compte.')+`<div class="settings-width">${section('Lisibilité','Taille des textes et contrastes.',`<div class="section-body">${check('Agrandir les textes','large_text',s.large_text)}${check('Renforcer les contrastes','high_contrast',s.high_contrast)}${button('Enregistrer la lisibilité','settings.display','','primary')}</div>`)}${role()==='user'?section('Rappels et notifications','Choisissez vos préférences, puis activez cet appareil dans la section suivante.',`<div class="section-body">${check('Activer les rappels de pause','pause_enabled',s.pause_enabled)}${select('Fréquence des pauses','pause_minutes',[30,45,60,90].map(v=>[v,v+' minutes']),s.pause_minutes||45)}${[['pause','Pauses'],['advice','Nouveau conseil'],['report','Bilan disponible'],['support','Réponse du support'],['calibration','Calibration nécessaire']].map(([k,l])=>select(l,'channel_'+k,[['both','Téléphone et montre'],['phone','Téléphone'],['watch','Montre'],['none','Aucun']],s.channels?.[k]||'none')).join('')}<p class="footnote">Les alertes de nouvelle connexion restent dans le dashboard. La montre seule n’est pas prise en charge : aucun envoi sur le téléphone ne la remplace. Pour un relais vers une montre appairée, choisissez les deux et configurez les notifications dans les réglages du téléphone et de la montre.</p><div class="form-columns">${field('Début des horaires silencieux','quiet_start',s.quiet_start||'19:00','time')}${field('Fin des horaires silencieux','quiet_end',s.quiet_end||'08:00','time')}</div><div class="action-grid">${button('Enregistrer les préférences','settings.notifications','','primary')}${button('Reporter le prochain rappel','pause.snooze','','secondary')}</div></div>`):''}${role()==='user'?section('Notifications sur cet appareil','Activation uniquement à votre demande.',window.SkeliviaPush?.panel()||empty('Vérification de disponibilité')):''}${role()!=='employer'?section('Sessions du compte','Les sessions de votre compte uniquement.',`<div class="section-body">${button('Gérer les sessions','sessions','','secondary')}</div>`):''}${role()==='user'?section('Compte et données','Demande et suivi de suppression.',`<div class="section-body">${collection('deletions').map(d=>`<p>${esc(d.id)} · ${badge(d.status)} · ${date(d.created_at)}</p>`).join('')}${button('Demander la suppression','deletion.request','','danger')}</div>`):''}</div>`;}
function render(){if(!st.data)return;const r=role(),menuItems=navs[r];if(r==='user')window.SkeliviaPush?.configure({account:st.session.user.id,request:api,notify:toast,failure,changed:()=>{if(st.data&&st.page==='settings')render();}});else window.SkeliviaPush?.reset();$('#workspace').hidden=false;$('#login-screen').hidden=true;$('#environment-bar').textContent=st.data.synthetic?'Banc local · Données synthétiques · Résultats matériels soumis à vérification':'SKELIVIA · Espace authentifié';$('#environment-bar').title=$('#environment-bar').textContent;$('#space-label').textContent='Espace '+roles[r];$('#topbar-space').textContent='SKELIVIA';$('#topbar-title').textContent=menuItems.find(n=>n[0]===st.page)?.[1]||'Dossier autorisé';$('#sidebar-description').textContent='Les informations sont limitées aux autorisations de votre compte.';$('#account-label').textContent=st.session.user.name||st.session.user.username;$('#account-role').textContent=roles[r];$('#account-avatar').textContent=(st.session.user.name||'').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();$('#notifications').innerHTML=icon('bell');$('#notifications').dataset.unread=String(collection('notifications').some(n=>!n.read));$('#navigation').innerHTML=menuItems.map(([page,text])=>`<button class="nav-item" data-action="page:${page}" ${st.page===page||(st.page==='patient'&&page==='home')?'aria-current="page"':''}>${icon(page)}<span>${text}</span></button>`).join('');document.documentElement.classList.toggle('large-text',Boolean(st.data.settings?.large_text));document.documentElement.classList.toggle('high-contrast',Boolean(st.data.settings?.high_contrast));let html='';if(st.page==='settings')html=settings();else if(st.page==='help'&&['user','clinician'].includes(r))html=helpPage();else if(r==='user')html=({home:userHome,measures:measuresPage,device:devicePage,shares:sharesPage}[st.page]||userHome)();else if(r==='clinician')html=st.page==='patient'?patientPage():st.page==='recommendations'?header('Prévention collective','Recommandations','Actions organisationnelles sans contenu médical.',button('+ Publier','recommendation.publish','','primary'))+section('Recommandations publiées','',recommendations()):st.page==='reminders'?header('Vos rappels','Dossiers à réexaminer','',button('+ Ajouter','reminder.create','','primary'))+section('Calendrier de suivi','',reminders()):clinicianHome();else if(r==='employer')html=st.page==='history'?history():employerHome();else if(r==='support')html=st.page==='maintenance'?maintenance():supportHome();else if(r==='security')html=({home:adminHome,accounts:accountsPage,certificates,proofs,components,audit,deletions,patches:()=>header('Évaluation des correctifs','Mises à jour','Priorité, exposition et résultats de tests.')+section('Correctifs','',patches()),incidents:()=>header('Surveillance des accès','Alertes & incidents','Qualification et suivi des événements.')+section('Événements','',incidents())}[st.page]||adminHome)();$('#content').innerHTML=html;setupTables();}
const byId=(name,ident)=>collection(name).find(x=>same(x.id,ident));
function confirmAction(title,text,action,payload,submit='Confirmer'){actionForm(title,`<p>${esc(text)}</p>`,action,payload,()=>({}),submit);}
function sessions(accountId=st.session.user.id){const rows=collection('sessions').filter(s=>!s.account_id||same(s.account_id,accountId));dialog('Sessions du compte',`<p>${esc(accountId)}</p>`+table(['Session','Dernière activité','Expiration','Action'],rows.map(s=>[esc(s.name||s.device_name||s.id),date(s.last_seen),date(s.expires),s.current?badge('Session actuelle'):button('Déconnecter','session.revoke',s.id,'secondary small')])));}
function documentHistory(ident){if(!access())return;const versions=docs().filter(d=>same(d.document_id||d.id,ident)).sort((a,b)=>Number(b.version)-Number(a.version));dialog('Historique des versions',versions.map(d=>`<article class="advice"><h3>${esc(d.title)} · version ${esc(d.version)}</h3><p class="document-text">${esc(d.body)}</p><small>${date(d.created_at)} · ${esc(author(d))}</small></article>`).join('')||empty(),'','',{patient:st.patient});}
function compare(){if(!access())return;if(partialMeasures()){dialog('Comparaison indisponible',empty('Période incomplète','Chargez toutes les pages de la période avant de comparer.'));return;}const days=[...new Set(personMeasures().map(m=>String(m.recorded_at).slice(0,10)))].sort();if(!days.length){dialog('Comparer deux périodes',empty('Aucune période disponible'));return;}const options=days.map(d=>[d,day(d)]);dialog('Comparer deux périodes',`<div class="form-columns">${select('Début de la période A','a_start',options,days[0])}${select('Fin de la période A','a_end',options,days[0])}${select('Début de la période B','b_start',options,days.at(-1))}${select('Fin de la période B','b_end',options,days.at(-1))}</div><div id="comparison-result"></div><p class="help-text">Seules les dates et catégories autorisées sont comparées. Des durées ou calibrations différentes limitent la comparaison.</p>`,'Comparer',form=>{if(form.get('a_start')>form.get('a_end')||form.get('b_start')>form.get('b_end'))throw Error('Vérifiez les bornes de chaque période.');const groups=['a','b'].map(side=>{const rows=personMeasures().filter(m=>{const d=String(m.recorded_at).slice(0,10);return d>=form.get(side+'_start')&&d<=form.get(side+'_end');});return `<div><h3>Période ${side.toUpperCase()}</h3><p>${day(form.get(side+'_start'))} – ${day(form.get(side+'_end'))}</p>${metrics.map(([key,title,unit])=>{const values=rows.map(m=>measureValue(m,key)).filter(v=>typeof v==='number');return `<p>${title} : <strong>${values.length?(key==='thumb_pct'?pressureSummary(rows).value:values.reduce((a,b)=>a+b,0)):'Non disponible'}</strong> ${values.length?unit:''}</p>${key==='thumb_pct'?`<small>${esc(pressureSummary(rows).caption)}</small>`:''}`;}).join('')}<p>Calibrations : ${[...new Set(rows.map(m=>m.calibration||'Non renseignée'))].map(esc).join(', ')}</p></div>`;});const duration=side=>(new Date(form.get(side+'_end'))-new Date(form.get(side+'_start')))/864e5+1,calibrations=side=>[...new Set(personMeasures().filter(m=>{const d=String(m.recorded_at).slice(0,10);return d>=form.get(side+'_start')&&d<=form.get(side+'_end');}).map(m=>m.calibration||'unknown'))].sort().join('|');const warnings=[];if(duration('a')!==duration('b'))warnings.push('Durées différentes : les cumuls ne sont pas directement comparables.');if(calibrations('a')!==calibrations('b')||calibrations('a').includes('|')||calibrations('b').includes('|'))warnings.push('Références de calibration différentes : comparaison limitée.');if(calibrations('a').includes('unknown')||calibrations('b').includes('unknown'))warnings.push('Une référence de calibration est inconnue.');if(form.get('a_start')===form.get('b_start')&&form.get('a_end')===form.get('b_end'))warnings.push('Vous comparez la même période.');$('#comparison-result').innerHTML=`<div class="comparison">${groups.join('')}</div>${warnings.length?`<div class="notice warn">${warnings.map(esc).join(' ')}</div>`:''}`;}, {patient:st.patient});}
async function exportFile(kind,params={}){const query=new URLSearchParams({kind,...params});const response=await fetch('/api/export?'+query,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok){const e=new Error('L’export n’est plus disponible pour ce compte.');e.status=response.status;throw e;}const blob=new Blob([await response.text()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SKELIVIA-'+kind+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeDialog();toast('Export téléchargé. Conservez-le dans un emplacement protégé.');}
function reauthenticate(){if(st.session?.environment?.auth==='oidc'){dialog('Confirmer votre identité','<p>Une authentification récente est nécessaire pour cette action. Reconnectez-vous, puis relancez la demande.</p><a class="button primary" href="/oidc/login?reauth=1">Réauthentifier avec Keycloak</a>');return;}dialog('Confirmer votre identité',field('Mot de passe','password','','password','required autocomplete="current-password"')+field('Code temporaire','otp','','text','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"')+'<p class="help-text">Après confirmation, relancez l’action souhaitée.</p>','Réauthentifier',async f=>{let result;try{result=await api('/api/reauth',{method:'POST',body:{password:f.get('password'),otp:f.get('otp')}});}catch(e){$('#dialog-form [name="password"]').value='';$('#dialog-form [name="otp"]').value='';if(e.status===401)throw new Error('Mot de passe ou code temporaire incorrect. Réessayez avec un nouveau code.');throw e;}st.session=result;st.csrf=result.csrf_token||st.csrf;closeDialog();await reload();toast('Identité confirmée. Vous pouvez relancer votre action.');});}
async function handle(action,ident=''){
 if(action.startsWith('push.')){await window.SkeliviaPush?.handle(action,ident);return;}
 if(action==='reauth'){reauthenticate();return;}
 if(action.startsWith('page:')){go(action.slice(5));return;}
 if(action==='logout'){await api('/api/logout',{method:'POST',body:{}});clearWorkspace();st.session=null;await loadSession();return;}
 if(action==='refresh'){await reload();return;}
 if(action==='patient'){await reload();const p=byId('patients',ident);if(!p?.access){toast('Le dossier n’est pas accessible.');return;}st.patient=p.id;st.tab='measures';st.measurePage=null;await loadMeasures();go('patient');return;}
 if(action==='compare'){await reload(true);compare();return;}
 if(action==='measures.more'){await loadMeasures(true);render();return;}
 if(action==='share.create'){const c=collection('clinicians');if(!c.length){dialog('Nouveau partage',empty('Aucun soignant habilité','Une relation de suivi doit être établie avant de partager vos mesures.'));return;}actionForm('Choisir un partage',select('Soignant habilité','clinician_id',c.map(x=>[x.id,x.name]))+`<div class="form-columns">${field('Début des mesures','start','','date')}${field('Fin des mesures','end','','date')}</div>`+field('Durée d’accès en heures','duration_hours',168,'number','required min="1" max="2160"')+['contact','pressure','moves'].map(k=>check(label(k),k,true)).join(''),'share.create',{},f=>{if(f.get('start')>f.get('end'))throw Error('La fin doit suivre le début.');const categories=['contact','pressure','moves'].filter(k=>f.has(k));if(!categories.length)throw Error('Choisissez au moins une catégorie.');return {clinician_id:f.get('clinician_id'),start:f.get('start'),end:f.get('end'),duration_hours:Number(f.get('duration_hours')),categories};});return;}
 if(action==='share.revoke'){confirmAction('Révoquer le partage','Le soignant ne pourra plus consulter les données au titre de ce partage.','share.revoke',{id:ident},'Révoquer');return;}
 if(action==='document.new'||action==='document.edit'){if(!access())return;const d=action==='document.edit'?byId('documents',ident):null,kind=d?.kind||ident;if(!['advice','report'].includes(kind))return;actionForm(kind==='advice'?'Publier un conseil':'Publier un bilan',field('Titre','title',d?.title||'','text','required maxlength="160"')+textarea('Contenu destiné au patient','body',d?.body||'')+'<p class="help-text">Une nouvelle version conserve les publications précédentes.</p>','document.publish',{patient_id:st.patient,kind,...(d?{document_id:d.document_id||d.id}:{})},f=>({title:f.get('title'),body:f.get('body')}),'Publier');return;}
 if(action==='document.history'){await reload();documentHistory(ident);return;}
 if(action==='reminder.create'){const p=collection('patients');if(!p.length){dialog('Ajouter un rappel',empty('Aucune relation de suivi'));return;}actionForm('Programmer un réexamen',select('Patient suivi','patient_id',p.map(x=>[x.id,x.name]))+field('Date','due','','date')+textarea('Rappel personnel','body'),'reminder.create');return;}
 if(action==='reminder.delete'){confirmAction('Supprimer le rappel','Ce rappel personnel sera retiré.','reminder.delete',{id:ident},'Supprimer');return;}
 if(action==='recommendation.publish'||action==='recommendation.revise'){const previous=action==='recommendation.revise'?byId('recommendations',ident):null,orgs=collection('organisations');if(!previous&&!orgs.length){dialog('Publier une recommandation',empty('Aucune organisation accessible'));return;}actionForm('Publier une recommandation',(previous?'':select('Organisation','org_id',orgs.map(o=>[o.id,o.name||o.id])))+field('Titre de l’action','title',previous?.title||'','text','required maxlength="160"')+textarea('Aménagement ou organisation concernés','body',previous?.body||'')+select('Type','category',[['equipment','Équipement'],['layout','Aménagement'],['organisation','Organisation']],previous?.category)+'<p class="notice">Aucun nom de patient, symptôme, mesure individuelle ni conclusion médicale.</p>',action,previous?{id:ident}:{},f=>Object.fromEntries(f),previous?'Publier la modification':'Publier');return;}
 if(action==='ticket.create'||action==='device.loss'){const devices=collection('devices'),isUser=role()==='user';actionForm('Nouveau ticket technique',field('Objet','title','','text','required maxlength="160"')+select('Catégorie','category',isUser?[['connection','Connexion'],['calibration','Calibration'],['replacement','Remplacement'],['loss','Perte'],['software','Service logiciel']]:[['software','Service logiciel']],action==='device.loss'?'loss':'software')+(isUser&&devices.length?select('Appareil concerné','device_id',[['','Aucun appareil'],...devices.map(d=>[d.id,d.id])],action==='device.loss'?ident:''):'')+textarea('Description technique','body')+'<p class="help-text">N’incluez aucun dossier patient ni contenu médical.</p>','ticket.create',{},f=>{const p={title:f.get('title'),body:f.get('body'),category:f.get('category')};if(isUser&&f.get('device_id'))p.device_id=f.get('device_id');return p;});return;}
 if(action==='ticket.open'){st.ticket=ident;st.ticketOpen=true;render();window.scrollTo(0,0);return;}
 if(action==='ticket.back'){st.ticketOpen=false;render();return;}
 if(action==='help.open'){const t=byId('tickets',ident);if(t)dialog(t.title,`<p>${esc(t.id)} · ${badge(t.status)}</p>${thread(t)}${button('Ajouter une précision','ticket.reply',t.id,'primary')}`);return;}
 if(action==='ticket.reply'){actionForm('Échange technique',textarea('Message technique','body')+'<p class="help-text">Sans contenu médical ni identifiants de dossier patient.</p>','ticket.reply',{id:ident});return;}
 if(action==='ticket.status'){const t=byId('tickets',ident);actionForm('Statut de l’intervention',select('Statut','status',[['in_progress','En cours'],['waiting','En attente'],['resolved','Résolu']],t?.status)+'<p class="help-text">La clôture matérielle est refusée si les contrôles ou les résultats vérifiés manquent.</p>','ticket.status',{id:ident});return;}
 if(action==='ticket.checks'){const payload={id:ident};for(const k of ['connection','sensors','calibration'])payload[k]=Boolean($(`[data-check="${k}"]`)?.checked);await mutate('ticket.checks',payload);return;}
 if(action==='diagnostic.request'){actionForm('Demander un accès technique',field('Durée en minutes','duration_minutes',30,'number','required min="1" max="60"')+textarea('Motif de l’intervention','reason')+'<p class="notice">L’accès reste fermé jusqu’à l’accord du propriétaire.</p>','diagnostic.request',{id:ident},f=>({duration_minutes:Number(f.get('duration_minutes')),reason:f.get('reason')}),'Demander');return;}
 if(action==='diagnostic.revoke'){confirmAction('Fermer le diagnostic','Les informations et actions techniques temporaires seront retirées.','diagnostic.revoke',{id:ident},'Révoquer');return;}
 if(action==='diagnostic.approve'){confirmAction('Autoriser le diagnostic','Le support attribué pourra consulter les informations techniques nécessaires pendant la durée demandée. Aucune mesure d’usage ni donnée médicale n’est transmise.','diagnostic.approve',{id:ident},'Autoriser');return;}
 if(action==='device.calibrate'){const t=role()==='support'?ticket():null;actionForm('Calibration guidée',`<ol class="dialog-list"><li><strong>Préparer la souris</strong><p>Placez l’appareil sur une surface stable et vérifiez sa connexion.</p></li><li><strong>Lancer le contrôle</strong><p>Le service transmettra la commande à l’appareil associé.</p></li><li><strong>Consulter le résultat</strong><p>Le statut restera en attente jusqu’au retour d’un résultat vérifié. En cas d’échec, contactez le support.</p></li></ol>${check('L’appareil est prêt pour la calibration.','ready',false,true)}`,'device.calibrate',{device_id:ident,...(t?{ticket_id:t.id}:{})},()=>({}),'Demander la calibration');return;}
 if(action==='device.update'){const patches=collection('approved_patches');if(!patches.length){dialog('Mise à jour de la souris',empty('Aucun correctif matériel approuvé','L’administration sécurité doit approuver une version avant toute installation.'));return;}actionForm('Installer une version approuvée',select('Version approuvée','patch_id',patches.map(p=>[p.id,(p.title||p.id)+' · '+p.version]))+'<p class="notice">L’installation reste en attente jusqu’à son exécution et sa vérification par l’appareil.</p>','device.update',{ticket_id:ident},f=>({patch_id:f.get('patch_id')}),'Demander l’installation');return;}
 if(action==='device.replace'){actionForm('Remplacer une souris',field('Identifiant du nouvel appareil','new_device_id','','text','required maxlength="80"')+check('Association vérifiée avec le propriétaire.','verified',false,true)+'<p class="notice">La demande n’atteste pas encore l’association physique ou cryptographique du nouvel appareil.</p>','device.replace',{ticket_id:ident},f=>({new_device_id:f.get('new_device_id')}),'Demander le remplacement');return;}
 if(action==='security.report'){actionForm('Signaler une anomalie',textarea('Éléments techniques minimaux','body')+'<p class="notice">Aucun contenu médical, mot de passe, code temporaire ni secret.</p>','security.report',ident?{ticket_id:ident}:{});return;}
 if(action==='sessions'||action==='account.sessions'){sessions(ident||st.session.user.id);return;}
 if(action==='session.revoke'){actionForm('Déconnecter une session',textarea('Motif','reason'),'session.revoke',{id:ident},f=>({reason:f.get('reason')}),'Déconnecter');return;}
 if(action==='incident.open'){const i=byId('incidents',ident);if(!i)return;dialog(i.title||'Dossier d’incident',`<p>${esc(i.id)} · ${badge(i.status)}</p><p class="document-text">${esc(i.body||i.description)}</p><ul class="dialog-list">${arr(i.timeline||i.history).map(e=>`<li><strong>${esc(e.title||e.action||label(e.type||e.kind))}</strong><p class="document-text">${esc(e.body||e.reason||e.proof)}</p><small>${date(e.at||e.created_at)} · ${esc(e.actor_id||e.author_id)}</small></li>`).join('')}</ul>${i.status==='confirmed'?button('Ajouter une action','incident.action',i.id,'secondary')+button('Vérifier et clôturer','incident.close',i.id,'primary'):i.status==='closed'?`<p class="notice">${esc(i.proof||'Retour à la normale consigné dans le dossier.')}</p>`:button('Qualifier l’événement','incident.qualify',i.id,'primary')}`);return;}
 if(action==='incident.qualify'){actionForm('Qualifier l’événement',select('Qualification','status',[['confirmed','Incident confirmé'],['false_positive','Fausse alerte']])+textarea('Motif et éléments techniques','reason'),'incident.qualify',{id:ident});return;}
 if(action==='incident.action'){actionForm('Consigner une action',textarea('Action effectuée et résultat observé','body'),'incident.action',{id:ident});return;}
 if(action==='incident.close'){actionForm('Vérifier le retour à la normale',textarea('Vérification et référence de preuve','proof')+check('Le retour à la normale a été vérifié.','verified',false,true),'incident.close',{id:ident},f=>({proof:f.get('proof')}),'Clôturer');return;}
 if(action==='account.create'||action==='account.role'||action==='account.toggle'){const a=byId('accounts',ident),operation=action==='account.create'?'create':action==='account.role'?'role':a?.active?'suspend':'reactivate';const fields=operation==='create'?field('Nom du compte','name','','text','required maxlength="160"')+field('Identifiant de connexion','username','','text','required maxlength="120"')+field('Organisation','org_id','','text','required maxlength="80"'):'';actionForm('Demande de changement de compte',fields+(['create','role'].includes(operation)?select('Rôle demandé','role',Object.entries(roles),a?.role||'user'):'')+textarea('Motif','reason')+'<p class="notice">Une autre personne habilitée doit approuver cette demande. Aucun droit n’est modifié à cette étape.</p>','account.request',{operation,...(ident?{target_id:ident}:{})},f=>Object.fromEntries([...f].filter(([k,v])=>v!=='')),'Créer la demande');return;}
 if(action==='account.approve'){const r=byId('account_requests',ident);confirmAction('Approuver la demande',`Opération : ${r?.operation||''}. Cible : ${r?.target_id||r?.username||''}. L’approbation exige un administrateur distinct et une authentification récente.`,'account.approve',{id:ident},'Approuver');return;}
 if(action==='certificate.renew'||action==='certificate.revoke'){actionForm(action.endsWith('renew')?'Renouveler le certificat':'Révoquer le certificat',textarea('Motif technique','reason')+'<p class="notice">L’autorité de certification doit exécuter la demande. Le résultat restera en attente jusqu’à vérification.</p>','certificate.request',{device_id:ident,operation:action.endsWith('renew')?'renew':'revoke'},f=>({reason:f.get('reason')}),'Créer la demande');return;}
 if(action==='patch.evaluate'){const p=byId('patches',ident);actionForm('Évaluer le correctif',select('Priorité','priority',[['low','Faible'],['medium','Modérée'],['high','Haute'],['critical','Critique']],p?.priority)+textarea('Exposition du projet','exposure',p?.exposure||'')+textarea('Tests et résultats vérifiés','tests',p?.tests||'')+select('Décision','decision',[['review','À examiner'],['approved','Approuver'],['deferred','Différer']],p?.decision||p?.status)+textarea('Motif de la décision','reason'),'patch.evaluate',{id:ident});return;}
 if(action==='deletion.request'){actionForm('Demander la suppression',textarea('Périmètre ou précision de la demande','reason')+'<p class="notice">La demande sera examinée selon les règles de conservation. Sa réception ne signifie pas que la suppression est exécutée.</p>','deletion.request');return;}
 if(action==='deletion.review'){actionForm('Examiner la suppression',textarea('Contrôles de conservation et décision de traitement','reason')+'<p class="notice">L’exécution et ses preuves seront consignées par le service dédié, sans consultation du contenu médical.</p>','deletion.review',{id:ident});return;}
 if(action==='access.check'){confirmAction('Contrôler les accès temporaires','Le service vérifiera les autorisations et expirations en base. Le résultat sera conservé dans les contrôles.','access.check',{},'Lancer le contrôle');return;}
 if(action==='settings.display'){await mutate('settings.save',{large_text:Boolean($('[name="large_text"]')?.checked),high_contrast:Boolean($('[name="high_contrast"]')?.checked)});return;}
 if(action==='settings.notifications'){const channels={};for(const k of ['pause','advice','report','support','calibration'])channels[k]=$(`[name="channel_${k}"]`).value;await mutate('settings.save',{pause_enabled:$('[name="pause_enabled"]').checked,pause_minutes:Number($('[name="pause_minutes"]').value),quiet_start:$('[name="quiet_start"]').value,quiet_end:$('[name="quiet_end"]').value,channels});return;}
 if(action==='pause.snooze'){actionForm('Reporter le prochain rappel',field('Report en minutes','minutes',10,'number','required min="1" max="120"'),'pause.snooze',{},f=>({minutes:Number(f.get('minutes'))}),'Reporter');return;}
 if(action==='export.prevention'){await exportFile('prevention');return;}
 if(action==='export.personal'){dialog('Télécharger vos mesures',`<div class="form-columns">${field('Début','start','','date')}${field('Fin','end','','date')}</div><p class="help-text">L’export inclut les unités, la qualité et les références de calibration disponibles.</p>`,'Télécharger',async f=>{if(f.get('start')>f.get('end'))throw Error('Vérifiez la période.');await exportFile('personal',{start:f.get('start'),end:f.get('end')});});return;}
 if(action==='notification.open'){const n=byId('notifications',ident);if(!n)return;await mutate('notification.read',{id:ident});const route=String(n.route||'');if(route.startsWith('http')||route.startsWith('/')){dialog(n.title,'<p>Cette notification a été marquée comme lue. Consultez les rubriques de votre espace pour son suivi.</p>');return;}const destinations={documents:role()==='clinician'?'home':'home',recommendations:role()==='employer'?'home':'recommendations',tickets:role()==='support'?'home':'help',advice:'home',report:'home',support:'help',ticket:'home',calibration:'device',security:'incidents',update:'patches',deletion:'deletions'};const page=destinations[route]||route;if(navs[role()].some(([p])=>p===page))go(page);else dialog(n.title,`<p>Notification reçue le ${date(n.created_at)}.</p><p>Consultez les informations disponibles dans votre espace.</p>`);return;}
}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();if(!e.target.reportValidity())return;$('#login-submit').disabled=true;$('#login-error').hidden=true;try{const result=await api('/api/login',{method:'POST',body:{username:$('#username').value,password:$('#password').value,otp:$('#otp').value}});$('#password').value='';$('#otp').value='';st.session=result;st.csrf=result.csrf_token||st.csrf;st.page='home';await loadSession();}catch(error){$('#login-error').textContent=error.status===401?'Identifiants ou code incorrects. Un code déjà utilisé doit être renouvelé.':error.message;$('#login-error').hidden=false;$('#password').value='';$('#otp').value='';}finally{$('#login-submit').disabled=false;}});
$('#retry-session').onclick=loadSession;
$('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();if(!e.target.reportValidity()||!dialogCallback)return;const callback=dialogCallback;$('#dialog-submit').disabled=true;$('#dialog-error').hidden=true;try{await callback(new FormData(e.target));}catch(error){if([401,403,404].includes(error.status))await failure(error);else{$('#dialog-error').textContent=error.message||'Enregistrement impossible. Réessayez.';$('#dialog-error').hidden=false;}}finally{$('#dialog-submit').disabled=false;}});
$('#dialog-close').onclick=closeDialog;$('#dialog-cancel').onclick=closeDialog;$('#dialog').addEventListener('close',()=>{if(dialogOpener?.isConnected)dialogOpener.focus();dialogCallback=null;st.dialogContext=null;});
$('#open-menu').onclick=()=>menu(true);$('#close-menu').onclick=()=>menu(false);$('#backdrop').onclick=()=>menu(false);
$('#account').onclick=()=>dialog('Votre compte',`<p><strong>${esc(st.session.user.name)}</strong></p><p>${esc(roles[role()])}</p><div class="action-grid">${button('Paramètres','page:settings','','secondary')}${role()!=='employer'?button('Mes sessions','sessions','','secondary'):''}${['user','clinician','support'].includes(role())?button('Signaler une connexion suspecte','security.report','','quiet'):''}${button('Réauthentifier','reauth','','secondary')}${button('Se déconnecter','logout','','danger')}</div>`);
$('#notifications').onclick=()=>dialog('Notifications',collection('notifications').length?`<ul class="dialog-list">${collection('notifications').map(n=>`<li><strong>${esc(n.title)}</strong><p>${date(n.created_at)}</p>${button(n.read?'Consulter':'Lire la notification','notification.open',n.id,'quiet small')}</li>`).join('')}</ul>`:empty('Aucune notification'));
$('#refresh').onclick=()=>reload().catch(failure);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b){if(b.disabled)return;const action=b.dataset.action;if(action.startsWith('page:'))closeDialog();b.disabled=true;try{await handle(action,b.dataset.id);}catch(error){await failure(error);}finally{if(b.isConnected)b.disabled=false;}}const p=e.target.closest('[data-period]');if(p){st.period=p.dataset.period;st.measurePage=null;try{await loadMeasures();render();}catch(error){await failure(error);}}const tab=e.target.closest('[data-tab]');if(tab){st.tab=tab.dataset.tab;render();$(`[data-tab="${st.tab}"]`)?.focus();}});
document.addEventListener('change',async e=>{if(e.target.id==='measure-end'){if(!e.target.value)return;st.measureEnd=e.target.value;st.measurePage=null;try{await loadMeasures();render();}catch(error){await failure(error);}return;}if(e.target.matches('[data-rec-status]')){const el=e.target;el.disabled=true;try{await mutate('recommendation.status',{id:el.dataset.recStatus,status:el.value});}catch(error){await failure(error);render();}finally{if(el.isConnected)el.disabled=false;}}});
document.addEventListener('input',e=>{if(e.target.id==='patient-search'){const q=e.target.value.toLocaleLowerCase();$$('.data-table tbody tr').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase().includes(q));}});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('#sidebar').classList.contains('open')){const focusables=$$('a,button:not(:disabled),[tabindex="0"]',$('#sidebar')).filter(el=>el.getClientRects().length);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))menu(false);if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role="tab"]'),index=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){closeDialog();st.epoch++;for(const controller of st.requests)controller.abort();if(st.session?.authenticated){st.data=null;st.measurePage=null;measuresSequence++;$('#content').replaceChildren();}}else if(st.session?.authenticated)reload().catch(failure);});
window.addEventListener('pageshow',e=>{if(e.persisted){clearWorkspace();loadSession();}});
window.addEventListener('resize',()=>{if(!matchMedia('(max-width:800px)').matches&&$('#sidebar').classList.contains('open'))menu(false);$$('.table-scroll-hint').forEach(e=>e.remove());setupTables();});
setInterval(()=>{if(!document.hidden&&st.session?.authenticated)reload(true).catch(failure);},15000);
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',event=>{if(event.origin&&event.origin!==location.origin)return;if(event.data?.type!=='SKELIVIA_OPEN_NOTIFICATIONS')return;st.openNotifications=true;if(st.session?.authenticated)reload().then(()=>{st.openNotifications=false;$('#notifications').click();}).catch(failure);});
loadSession();
})();
